-- Landmark meshes, generated by model/scripts/landmarks_sql.py from model/out/landmarks-manifest.json.
-- Live destination ids differ from the seed's, so rows are matched by slug. Idempotent.
DO $$
DECLARE n integer;
BEGIN
  DELETE FROM "landmarks" WHERE "destination_id" = (SELECT "id" FROM "destinations" WHERE "slug" = 'baguio-cathedral');
  INSERT INTO "landmarks" ("id", "destination_id", "mesh_url", "mesh_scale", "rotation_deg", "altitude_m")
  SELECT gen_random_uuid()::text, "id", '/models/landmarks/baguio-cathedral.1a6af15c.glb', 1, 0, 0 FROM "destinations" WHERE "slug" = 'baguio-cathedral';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'landmarks: baguio-cathedral expected 1 row, inserted %', n; END IF;
  DELETE FROM "landmarks" WHERE "destination_id" = (SELECT "id" FROM "destinations" WHERE "slug" = 'burnham-park');
  INSERT INTO "landmarks" ("id", "destination_id", "mesh_url", "mesh_scale", "rotation_deg", "altitude_m")
  SELECT gen_random_uuid()::text, "id", '/models/landmarks/burnham-park.440e9cdc.glb', 1, 0, 0 FROM "destinations" WHERE "slug" = 'burnham-park';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'landmarks: burnham-park expected 1 row, inserted %', n; END IF;
  DELETE FROM "landmarks" WHERE "destination_id" = (SELECT "id" FROM "destinations" WHERE "slug" = 'session-road');
  INSERT INTO "landmarks" ("id", "destination_id", "mesh_url", "mesh_scale", "rotation_deg", "altitude_m")
  SELECT gen_random_uuid()::text, "id", '/models/landmarks/session-road.461fe017.glb', 1, 0, 0 FROM "destinations" WHERE "slug" = 'session-road';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'landmarks: session-road expected 1 row, inserted %', n; END IF;
END
$$;
